// node tools/browser_vectors.mjs <chromium|firefox|webkit> [executablePath]
// Assumes the repository root is served at http://localhost:8766/ and inputs were
// generated by tools/prepare_vec_tmp.sh.
import { chromium, firefox, webkit } from 'playwright';
const kind = process.argv[2];
const browserType = { chromium, firefox, webkit }[kind];
const opts = process.argv[3] ? { executablePath: process.argv[3] } : {};
const browser = await browserType.launch(opts);
const page = await browser.newPage();
await page.goto('http://localhost:8766/web/vectors/index.html');
await page.waitForFunction(() => window.__results !== undefined, null, { timeout: 30 * 60 * 1000 });
const res = await page.evaluate(() => window.__results);
console.log(kind, browser.version(), JSON.stringify(res));
await browser.close();
if (!res.every(r => r.ok)) process.exit(1);
